using System.Runtime.InteropServices; namespace TVOS; internal static class InputManager { [StructLayout(LayoutKind.Sequential)] struct INPUT{public uint type;public U U;} [StructLayout(LayoutKind.Explicit)] struct U{[FieldOffset(0)]public KEY k;} [StructLayout(LayoutKind.Sequential)] struct KEY{public ushort vk,scan;public uint flags,time;public IntPtr extra;} [DllImport("user32.dll")]static extern uint SendInput(uint n,INPUT[] i,int s); public static void Key(ushort vk){var a=new[]{new INPUT{type=1,U=new U{k=new KEY{vk=vk}}},new INPUT{type=1,U=new U{k=new KEY{vk=vk,flags=2}}}};SendInput(2,a,Marshal.SizeOf<INPUT>());} public static void Text(string t){foreach(var c in t){var a=new[]{new INPUT{type=1,U=new U{k=new KEY{scan=c,flags=4}}},new INPUT{type=1,U=new U{k=new KEY{scan=c,flags=6}}}};SendInput(2,a,Marshal.SizeOf<INPUT>());}} }